body {
  margin: 0;
  background: transparent;
  color: #101828;
  font-family: Inter, Arial, sans-serif;
}

.panel {
  width: 100%;
  min-height: 100%;
  box-sizing: border-box;
  background: #ffffff;
  border: 1px solid #d0d5dd;
  border-radius: 8px;
  padding: 14px;
}

.top {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 14px;
  margin-bottom: 12px;
}

.eyebrow {
  font-size: 10px;
  text-transform: uppercase;
  font-weight: 900;
  color: #667085;
  letter-spacing: 0;
}

h1 {
  margin: 3px 0 0;
  font-size: 21px;
  line-height: 1.15;
}

.actions {
  display: flex;
  gap: 7px;
  flex-wrap: wrap;
  justify-content: flex-end;
}

button {
  height: 34px;
  border: 1px solid #d0d5dd;
  border-radius: 7px;
  background: #ffffff;
  color: #101828;
  font-size: 12px;
  font-weight: 800;
  padding: 0 11px;
  cursor: pointer;
}

button.primary {
  background: #101828;
  border-color: #101828;
  color: #ffffff;
}

.cards {
  display: grid;
  grid-template-columns: repeat(7, minmax(88px, 1fr));
  gap: 8px;
}

.card {
  border: 1px solid #d0d5dd;
  border-left-width: 4px;
  border-radius: 7px;
  padding: 9px 10px;
  background: #ffffff;
}

.card span {
  display: block;
  font-size: 10px;
  text-transform: uppercase;
  color: #667085;
  font-weight: 800;
}

.card strong {
  display: block;
  margin-top: 4px;
  font-size: 22px;
  line-height: 1;
}

.card.dark {
  border-left-color: #101828;
}

.card.blue {
  border-left-color: #2563eb;
}

.card.green {
  border-left-color: #16a34a;
}

.card.gray {
  border-left-color: #667085;
}

.card.orange {
  border-left-color: #f97316;
}

.card.red {
  border-left-color: #dc2626;
}

.bottom {
  display: grid;
  grid-template-columns: 280px 1fr;
  gap: 10px;
  margin-top: 10px;
}

.selected,
.alerts {
  border: 1px solid #d0d5dd;
  border-radius: 7px;
  padding: 10px;
}

.selected span,
.alerts-head span {
  display: block;
  font-size: 10px;
  text-transform: uppercase;
  color: #667085;
  font-weight: 800;
}

.selected strong {
  display: block;
  margin-top: 5px;
  font-size: 16px;
}

.selected small {
  display: block;
  margin-top: 4px;
  color: #667085;
  font-size: 11px;
}

.alerts-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.alerts-head b {
  min-width: 24px;
  height: 24px;
  border-radius: 999px;
  background: #101828;
  color: white;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 11px;
}

.alert-list {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 6px;
  margin-top: 8px;
}

.alert {
  border: 1px solid #eaecf0;
  border-left: 4px solid #f97316;
  border-radius: 6px;
  padding: 7px;
  min-width: 0;
}

.alert.high {
  border-left-color: #dc2626;
}

.alert.medium {
  border-left-color: #f97316;
}

.alert b {
  display: block;
  font-size: 12px;
}

.alert span {
  display: block;
  margin-top: 2px;
  color: #475467;
  font-size: 11px;
  line-height: 1.25;
}

.empty {
  color: #667085;
  font-size: 12px;
  padding: 8px 0;
}

@media (max-width: 900px) {
  .top,
  .bottom {
    grid-template-columns: 1fr;
    display: grid;
  }
  .cards {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .alert-list {
    grid-template-columns: 1fr;
  }
  .actions {
    justify-content: flex-start;
  }
}

