import React from "https://esm.sh/react@18.2.0";
import ReactDOM from "https://esm.sh/react-dom@18.2.0";

function num(value) {
  return Number(value || 0).toLocaleString("en-US");
}

function App() {
  const model = appsmith.model || {};
  const overview = model.overview || {};
  const alerts = model.alerts || [];

  const trigger = (action) => {
    appsmith.updateModel({ action });
    appsmith.triggerEvent("onDeliveryControlAction");
  };

  const cards = [
    { label: "Total", value: overview.totalDeliveries, tone: "dark" },
    { label: "Open", value: overview.openDeliveries, tone: "blue" },
    { label: "Packed", value: overview.packedDeliveries, tone: "green" },
    { label: "Shipped", value: overview.shippedDeliveries, tone: "gray" },
    { label: "Packages", value: overview.totalPackages, tone: "dark" },
    { label: "No Barcode", value: overview.packagesMissingBarcode, tone: "orange" },
    { label: "No Manifest", value: overview.packagesWithoutManifest, tone: "red" }
  ];

  return (
    <div className="panel">
      <div className="top">
        <div>
          <div className="eyebrow">Delivery Control</div>
          <h1>Shipment Readiness</h1>
        </div>

        <div className="actions">
          <button onClick={() => trigger("refresh")}>Refresh</button>
          <button onClick={() => trigger("printDelivery")}>Print Delivery</button>
          <button onClick={() => trigger("printLabels")}>Labels</button>
          <button className="primary" onClick={() => trigger("addToManifest")}>Add to Manifest</button>
        </div>
      </div>

      <div className="cards">
        {cards.map((card) => (
          <div className={`card ${card.tone}`} key={card.label}>
            <span>{card.label}</span>
            <strong>{num(card.value)}</strong>
          </div>
        ))}
      </div>

      <div className="bottom">
        <div className="selected">
          <span>Selected delivery</span>
          <strong>{model.selectedDocumentNumber || "No delivery selected"}</strong>
          <small>
            Manifest: {model.selectedManifestId ? `#${model.selectedManifestId}` : "not selected"}
          </small>
        </div>

        <div className="alerts">
          <div className="alerts-head">
            <span>Alerts</span>
            <b>{alerts.length}</b>
          </div>

          <div className="alert-list">
            {alerts.length === 0 ? (
              <div className="empty">No delivery issues found.</div>
            ) : (
              alerts.slice(0, 6).map((alert, index) => (
                <div className={`alert ${String(alert.severity || "").toLowerCase()}`} key={index}>
                  <b>{alert.documentNumber || "-"}</b>
                  <span>{alert.message || ""}</span>
                </div>
              ))
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

function render() {
  ReactDOM.render(<App />, document.getElementById("root"));
}

appsmith.onReady(() => {
  render();
  appsmith.onModelChange(render);
});
